/**
 * Measured voice timing, generated by `npm run voice:prepare`.
 *
 * The manifest is the single source of truth for VO start frames, VO end
 * frames, word-level subtitles and caption slam frames. Nothing here is
 * authored by hand: every value comes from ffmpeg measuring the actual clip.
 * It is a TS module rather than JSON so plain Node (check scripts) can import
 * it with the same code the renderer uses.
 */
import { VOICE_MANIFEST } from "./voiceManifest.ts";

export type ClipWord = {
  word: string;
  /** Absolute composition frame. */
  startFrame: number;
  endFrame: number;
};

export type ClipTiming = {
  id: string;
  source: string;
  audio: string;
  sceneStartFrame: number;
  audioStartFrame: number;
  speechStartFrame: number;
  speechEndFrame: number;
  durationSeconds: number;
  leadSilenceSeconds: number;
  trailingSilenceSeconds: number;
  speechSeconds: number;
  windowFrames: number;
  windowSeconds: number;
  availableSeconds: number;
  tempo: number;
  fits: boolean;
  overSeconds: number;
  slamFrame: number;
  slamWord: string;
  slamWordIndex: number;
  keywordFrame: number;
  slamDeltaFrames: number;
  words: ClipWord[];
};

const data = VOICE_MANIFEST as { fps: number; clips: ClipTiming[] };

export const MANIFEST_FPS = data.fps;

export const CLIP_TIMINGS: Record<string, ClipTiming> = Object.fromEntries(
  data.clips.map((clip) => [clip.id, clip]),
);

export const TIMING_ORDER: ClipTiming[] = data.clips;

/** Absolute caption slam frame per clip id (hook, m1 ... payoff, end). */
export const SLAM_FRAME: Record<string, number> = Object.fromEntries(
  data.clips.map((clip) => [clip.id, clip.slamFrame]),
);
